    "order": 8,
    "folderPath": "/home/edvins/features-for-web/web-for-options/features/faq-accordion-smooth",
    "relativePath": "features/faq-accordion-smooth",
    "previewUrl": "features/faq-accordion-smooth/index.html",
    "liveSiteUrl": null,
    "adminUrl": null,
